CREATE TABLE IF NOT EXISTS institutional_due_diligence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), institution_id uuid NOT NULL REFERENCES institutional_profiles(id) ON DELETE CASCADE, project_id uuid REFERENCES projects(id) ON DELETE CASCADE, asset_id uuid REFERENCES assets(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'requested', scope jsonb NOT NULL DEFAULT '{}'::jsonb, findings jsonb NOT NULL DEFAULT '[]'::jsonb, opened_by text, opened_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);